def answer_question(text: str, calories: int | None, goal: str | None, measurement_count: int) -> str:
    query = text.lower().replace("ё", "е")
    if any(word in query for word in ("калори", "кбжу", "белок", "жир", "углевод")):
        target = f"Ваш текущий ориентир — около {calories} ккал в день. " if calories else "У вас пока нет автоматического ориентира калорийности. "
        return target + "Оценивайте среднее питание и динамику за несколько недель, а не один отдельный день. Значения FORMETR не являются медицинским назначением."
    if any(word in query for word in ("вес", "похуд", "набрать")):
        return "Вес может ежедневно меняться из-за воды, соли, углеводов и содержимого ЖКТ. Вносите средний вес за неделю и оценивайте тенденцию минимум за 3–4 недели. Не снижайте калорийность по одному взвешиванию."
    if any(word in query for word in ("прогресс", "талия", "замер", "объем", "объём")):
        suffix = f" Сейчас сохранено записей: {measurement_count}." if measurement_count else " Добавьте первый показатель в разделе «Замеры»."
        return "Измеряйте один и тот же обхват утром, в одинаковых условиях и одной техникой. Выводы делаются по нескольким точкам, а не по одному значению." + suffix
    if any(word in query for word in ("меню", "блюд", "продукт", "грам")):
        return "Меню FORMETR показывает массу каждого ингредиента и ориентировочные КБЖУ. Для круп учитывайте состояние из названия — сухое или готовое. Фактические значения сверяйте с этикеткой конкретного продукта. Ограничения можно сохранить в разделе «Мои ограничения»."
    if any(word in query for word in ("аллерг", "лактоз", "неперенос")):
        return "Укажите аллерген или непереносимый продукт в разделе «Мои ограничения». FORMETR исключит распознанные продукты, но при выраженной аллергии обязательно проверяйте состав, следы аллергенов и перекрёстное загрязнение самостоятельно."
    return "Я могу помочь с меню, КБЖУ, весом, замерами, пищевыми ограничениями и оценкой прогресса. Сформулируйте вопрос, например: «Почему вес стоит?» или «Как учитывать сухую крупу?»."
